// Converted Java method
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.ArrayList;
import java.util.List;
import java.util.Collections;

class EnhancedTestUtils {

    /**
     * Enhanced version of createList that includes validation and transformation capabilities.
     * Creates a list of specified size with elements generated by the supplier,
     * optionally validating and transforming each element.
     *
     * @param <T> Type of list elements
     * @param count Number of elements to create
     * @param supplier Element generator
     * @param validator Optional validation consumer (can be null)
     * @param transformer Optional transformation function (can be null)
     * @return List of generated elements
     * @throws IllegalArgumentException if count is negative or supplier is null
     * @throws RuntimeException if validator throws for any element
     */
    public static <T, R> List<R> createEnhancedList(
            int count,
            Supplier<T> supplier,
            Consumer<T> validator,
            java.util.function.Function<T, R> transformer) {

        if (count < 0) {
            throw new IllegalArgumentException("Count must be >= 0");
        }
        if (supplier == null) {
            throw new IllegalArgumentException("Supplier cannot be null");
        }

        List<R> result = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            T element = supplier.get();
            
            if (validator != null) {
                validator.accept(element);
            }
            
            R transformedElement = (transformer != null) ? 
                transformer.apply(element) : 
                (R) element;
                
            result.add(transformedElement);
        }

        return Collections.unmodifiableList(result);
    }

    /**
     * Creates an exception expectation wrapper that verifies both the exception type
     * and optionally the exception message or other properties.
     *
     * @param <T> Input type of the consumer
     * @param <E> Expected exception type
     * @param expectedExceptionClass Class of the expected exception
     * @param exceptionValidator Optional validator for the exception
     * @param consumer Consumer that should throw the exception
     * @return Wrapped consumer that verifies the exception
     */
    public static <T, E extends Exception> Consumer<T> enhancedExceptionExpectation(
            Class<E> expectedExceptionClass,
            Consumer<E> exceptionValidator,
            Consumer<? super T> consumer) {

        return input -> {
            try {
                consumer.accept(input);
                throw new AssertionError("Expected exception " + 
                    expectedExceptionClass.getSimpleName() + " was not thrown");
            } catch (Exception e) {
                if (!expectedExceptionClass.isInstance(e)) {
                    throw new AssertionError("Expected exception " + 
                        expectedExceptionClass.getSimpleName() + 
                        " but got " + e.getClass().getSimpleName(), e);
                }
                if (exceptionValidator != null) {
                    exceptionValidator.accept(expectedExceptionClass.cast(e));
                }
            }
        };
    }
}
